out=dict(scope='All safely inscribed whole native32 floor cells across each visible nook interior, plus doors. Partial edge pixels stay solid rather than cutting through furniture or bases.',rooms=rooms,allEightInteriorCellsUsable=True,excludedBoundaryCandidates=excluded,southWallFoliage='Leaves overhang the floor; source base pixels at y384 and below remain blocked, with leaf-only head-safe foreground. No opaque wood-floor rectangle is placed above avatars.')
